ext('c10_eng_ch14',[
C("🌳","कोयल का परिचय",["कोयल एक काली चिड़िया है","नर कोयल मीठा गाता है","बसंत और गर्मी में ज़्यादा सुनाई देती है","अपना घोंसला नहीं बनाती"],"कविता में उतरने से पहले कोयल को जान लेते हैं। कोयल एक काले रंग की चिड़िया है। नर कोयल बहुत मीठी और ऊँची कूक निकालता है। बसंत और गर्मी के मौसम में आम के बगीचों में इसकी आवाज़ ख़ूब सुनाई देती है। एक रोचक बात यह है कि कोयल अपना घोंसला नहीं बनाती। वह अपने अंडे कौए जैसे दूसरे पक्षियों के घोंसले में रख देती है। फिर भी भारतीय साहित्य में कोयल को मधुरता और बसंत का प्रतीक माना गया है। यह कविता उसी परंपरा की एक कड़ी है।"),
C("🎵","कूक का जादू",["ऊँचे सुर की कूक","सुनते ही मन चौंकता है","पुरानी यादें जाग उठती हैं","कवि की आत्मा झंकृत होती है"],"कविता की शुरुआत ही कूक की गूँज से होती है। कवि कहते हैं कि जब कोयल ऊँचे सुर में कूकती है, तो उनकी आत्मा में हज़ारों पुरानी यादें जाग उठती हैं। यह अनुभव हम सबने किया है। कोई पुराना गाना, कोई ख़ुशबू या कोई आवाज़ सुनते ही बचपन याद आ जाता है। कवि ने इसी भाव को कोयल की कूक से जोड़ा है। यहाँ आवाज़ सिर्फ़ आवाज़ नहीं रहती, वह यादों का दरवाज़ा खोलने वाली चाबी बन जाती है। यही इस कविता की सुंदरता है।"),
C("🖤","काला रंग, मीठी वाणी",["कोयल का रंग जला हुआ सा काला","पर आवाज़ बहुत मधुर","रूप और गुण का विरोध","असली सुंदरता गुणों में"],"कवि कोयल को देखकर एक कल्पना करते हैं कि यह काली इसलिए है, जैसे किसी आग में जल गई हो, शायद विरह की आग में। फिर भी उसका गीत कितना मीठा है! यहाँ रंग और आवाज़ का सुंदर विरोध है। दिखने में काली, पर गुणों में अनमोल। यह हमें सिखाता है कि इंसान की क़ीमत उसके रंग-रूप से नहीं, उसके गुणों से तय होनी चाहिए। किसी को रंग या शक्ल के आधार पर कमतर मत समझिए। मधुर वाणी और अच्छा स्वभाव सबसे बड़ी सुंदरता है।"),
C("💔","विरह और प्रेम का प्रतीक",["विरह यानी बिछड़ने की पीड़ा","कोयल को प्रेमी का प्रतीक माना गया","जलकर भी मधुर गाना","दुख में भी सुंदर रहना"],"हमारे साहित्य में कोयल को अक्सर विरह और प्रेम का प्रतीक माना जाता है। विरह का मतलब है अपने प्रिय से बिछड़ने की पीड़ा। कवि को लगता है कि कोयल की मधुर कूक में भी एक कसक छिपी है, जैसे वह अपने प्रिय को पुकार रही हो। फिर भी वह गाना नहीं छोड़ती। यह हमें सिखाता है कि दुख में भी हम अपने भीतर की मिठास और सुंदरता को बनाए रख सकते हैं। यह प्रतीक कविता को गहराई देता है, इसलिए परीक्षा में इसे अवश्य लिखिए।"),
C("✍️","पूरन सिंह का परिचय",["पंजाब के कवि और निबंधकार","रसायनशास्त्री भी थे","अंग्रेज़ी, पंजाबी और हिंदी में लेखन","प्रकृति और प्रेम पर लिखा"],"अब कवि पूरन सिंह के बारे में जान लें। वे पंजाब के कवि और निबंधकार थे, और दिलचस्प बात यह है कि वे एक रसायनशास्त्री भी थे। यानी विज्ञान और कविता, दोनों में उनकी रुचि थी। उन्होंने पंजाबी, अंग्रेज़ी और हिंदी में लिखा। उनके निबंध सच्ची वीरता और मज़दूरी और प्रेम बहुत प्रसिद्ध हैं। उनकी रचनाओं में प्रकृति, प्रेम और इंसानियत की गहरी भावना मिलती है। परीक्षा में कवि का नाम, प्रदेश और उनकी रचनाओं का ज़िक्र अक्सर पूछा जाता है।"),
C("🎨","ध्वनि और रंग के बिंब",["कूक की ध्वनि का बिंब","काले रंग का दृश्य बिंब","आम का बगीचा और गर्मी","पाठक को दृश्य और ध्वनि दोनों मिलते हैं"],"इस कविता में दो तरह के बिंब हैं। पहला ध्वनि का बिंब, यानी कोयल की ऊँची कूक, जो पढ़ते हुए हमारे कानों में गूँजती सी लगती है। दूसरा दृश्य का बिंब, यानी कोयल का जला हुआ सा काला रंग। जब कविता हमारी आँख और कान, दोनों को छू लेती है, तो उसका असर कई गुना बढ़ जाता है। कविता पढ़ते समय आँखें बंद कीजिए और कोयल की कूक की कल्पना कीजिए। अगर हो सके तो इंटरनेट पर कोयल की आवाज़ भी एक बार सुनिए।"),
C("📝","शब्दार्थ दोहराइए",["चार्ड यानी जला हुआ","नोट्स यानी सुर","सोल यानी आत्मा","मेमोरीज़ और लॉन्गिंग"],"आइए शब्द दोहराते हैं। चार्ड यानी जला हुआ, नोट्स यानी सुर, सोल यानी आत्मा, मेमोरीज़ यानी यादें और लॉन्गिंग यानी तड़प या गहरी चाह। साथ में स्वीट यानी मीठा और हाई यानी ऊँचा जैसे आसान शब्द भी याद रखिए। एक अभ्यास कीजिए। हर शब्द से अपना एक वाक्य बनाइए, जैसे द कोयल हैज़ अ स्वीट वॉइस। फिर उन्हें कॉपी में लिखिए। वाक्य में इस्तेमाल करने से शब्द हमेशा के लिए याद रहते हैं।"),
C("🔤","विशेषण को गहराई से समझें",["विशेषण संज्ञा की ख़ासियत बताता है","अंग्रेज़ी में संज्ञा से पहले आता है","ब्लैक बर्ड, स्वीट वॉइस","तुलना में एर और एस्ट"],"आज का व्याकरण विशेषण यानी एडजेक्टिव है। विशेषण वह शब्द है जो संज्ञा की ख़ासियत बताता है। जैसे स्वीट वॉइस में स्वीट विशेषण है और वॉइस संज्ञा। अंग्रेज़ी में विशेषण हमेशा संज्ञा से पहले आता है, हिंदी की तरह। जैसे ब्लैक बर्ड, यानी काली चिड़िया। तुलना के लिए विशेषण में एर और एस्ट जुड़ते हैं। जैसे स्वीट, स्वीटर, स्वीटेस्ट। कोयल इज़ स्वीटर दैन अ क्रो, यानी कोयल कौए से ज़्यादा मीठी है। इस कविता से पाँच विशेषण चुनिए और उनसे वाक्य बनाइए।"),
C("🍃","बिहार की कोयल और लोकगीत",["आम के बगीचे और बसंत","चैता और फगुआ में कोयल","भोजपुरी, मैथिली गीतों में ज़िक्र","प्रकृति से जुड़ी हमारी संस्कृति"],"बिहार में बसंत आते ही आम में मंजरी लगती है और कोयल कूकने लगती है। हमारे चैता, फगुआ और कई लोकगीतों में कोयल का ज़िक्र मिलता है। भोजपुरी और मैथिली गीतों में कोयल को संदेश लाने वाली माना गया है। इसका मतलब है कि कविता में जिस कोयल की बात है, वह हमारे अपने आँगन की भी चिड़िया है। प्रकृति और संस्कृति का यह रिश्ता हमें बहुत कुछ सिखाता है। इसलिए पेड़ लगाइए और पक्षियों के लिए छत पर पानी रखिए, ताकि कोयल की कूक हमेशा सुनाई देती रहे।"),
C("🧠","यादों का महत्व",["यादें हमारी पहचान हैं","बचपन की यादें सुख देती हैं","बुज़ुर्गों से कहानियाँ सुनिए","अपनी यादें डायरी में लिखिए"],"कविता में यादों की बात बहुत महत्वपूर्ण है। हमारी यादें ही हमारी पहचान बनाती हैं। बचपन की यादें, नानी के घर की यादें, दोस्तों के साथ खेलने की यादें, ये हमें सुख और ऊर्जा देती हैं। इसलिए अपनी यादों को सँजोकर रखिए। एक अच्छी आदत है डायरी लिखना। रोज़ पाँच वाक्य अंग्रेज़ी में लिखिए कि आज क्या हुआ। इससे आपका लेखन भी सुधरेगा और भविष्य में पढ़कर आपको बहुत ख़ुशी होगी। बुज़ुर्गों से उनकी यादें और कहानियाँ भी सुनिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि कौन हैं","कोयल काली क्यों दिखाई गई","कूक का कवि पर क्या असर","कोयल किसका प्रतीक है"],"अब परीक्षा के प्रश्न देखते हैं। पहला, कवि कौन हैं? उत्तर, पूरन सिंह। दूसरा, कवि ने कोयल को काली क्यों बताया? उत्तर, जैसे वह विरह की आग में जलकर काली हो गई हो। तीसरा, कूक का कवि पर क्या असर होता है? उत्तर, उनकी आत्मा में हज़ारों पुरानी यादें जाग जाती हैं। चौथा, कोयल किसका प्रतीक है? उत्तर, सच्चे प्रेम, विरह और मधुरता का। लिखते समय पूरे वाक्य बनाइए और कविता के शब्दों का प्रयोग कीजिए, इससे अंक बढ़ते हैं।"),
Q("कौआ और कोयल दोनों काले हैं, फिर लोग कोयल को क्यों पसंद करते हैं?","क्योंकि कोयल की आवाज़ मधुर है। इंसान की पहचान भी रूप से नहीं, गुणों और बोली से होती है।","अब एक सोचने वाला प्रश्न। कौआ और कोयल दोनों काले हैं, फिर लोग कोयल को क्यों पसंद करते हैं? सोचिए। ... क्योंकि कोयल की आवाज़ बहुत मधुर है, जबकि कौए की कर्कश। इंसान की पहचान भी रूप से नहीं, बल्कि उसके गुणों और बोली से होती है। इसलिए हमेशा मीठा और अच्छा बोलने की आदत डालिए।"),
Q("कविता में कोयल की कूक का कवि के मन पर क्या प्रभाव पड़ता है?","कूक सुनकर कवि की आत्मा में हज़ारों पुरानी यादें जाग उठती हैं।","एक और प्रश्न। कविता में कोयल की कूक का कवि के मन पर क्या प्रभाव पड़ता है? सोचिए। ... उत्तर, कूक सुनकर कवि की आत्मा झंकृत हो जाती है और हज़ारों पुरानी यादें जाग उठती हैं। इसे पूरे वाक्य में अपनी कॉपी में लिखिए।"),
],7)
